from pathlib import Path
import json
import re

# The OPS_HR_TE workflow token appears with different separators depending on
# the source (Jira issue keys use OPS_HR_TE-<n>; the SOP prints OPS-HR-TE), so
# accept '-', '_', or ' ' between segments.
WORKFLOW_TOKEN = re.compile(r"ops[-_ ]hr[-_ ]te")

# Defensible renderings of March 28 2026 beyond the original token list
# (e.g. ISO 2026-03-28, 03-28, 28/03, '28 March', 'Mar. 28').
DATE_PATTERNS = [
    r"(?:march|mar)\.?\s*28",
    r"28(?:th)?\s*(?:of\s+)?(?:march|mar)\b",
    r"(?<!\d)0?3[/-]28(?!\d)",
    r"(?<!\d)28[-/.]0?3(?!\d)",
]

def verify(workspace_path, external_services_path=None):
