        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot locate slack_data.json"}

    slack_path = Path(external_services_path) / "slack_data.json"
    if not slack_path.exists():
        return {"pass": False, "score": 0.0, "feedback": f"slack_data.json not found at {slack_path}"}

    with open(slack_path, "r") as f:
        data = json.load(f)

    messages = data.get("messages", {})
    d002_messages = messages.get("D002", [])

    if not d002_messages:
        return {"pass": False, "score": 0.0, "feedback": "No messages found in Slack channel D002"}

    required_elements = [
        "t&e review flag",
        "emp-2103",
        "215",
        "capital grille",
        "calendar"
    ]

    for msg in d002_messages:
        text = msg.get("text", "").lower()
        # Check for march 28 date in various formats
        date_present = any(x in text for x in ["march 28", "mar 28", "03/28", "3/28", "28 march", "march 28th"]) or any(
            re.search(p, text) for p in DATE_PATTERNS
        )
        if all(elem in text for elem in required_elements) and WORKFLOW_TOKEN.search(text) and date_present:
            return {"pass": True, "score": 1.0, "feedback": "Found required T&E Review Flag message in D002 for EMP-2103 with all required details"}

    return {"pass": False, "score": 0.0, "feedback": "No message in D002 found containing all required elements: [T&E Review Flag], EMP-2103, $215, Capital Grille, calendar event reference, OPS_HR_TE, and March 28 2026 date"}

