        with open(mailbox_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Failed to read/parse mailbox.json: {e}"}

    emails = data.get("emails", [])
    if not isinstance(emails, list):
        return {"pass": False, "score": 0.0, "feedback": "'emails' field in mailbox.json is not a list."}

